INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',547,'{"_type":"chat:Message","id":"-5124234082:2804","threadId":"telegram:-5124234082","text":"Ce midi on a dejeuner dehors. Ce soir on va faire des dumplings. Donne moi la recette pour 12 dumplings.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Ce midi on a dejeuner dehors. Ce soir on va faire des dumplings. Donne moi la recette pour 12 dumplings.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":105,"offset":104}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":105,"offset":104}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":105,"offset":104}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-25T19:39:47.000Z","edited":false},"attachments":[],"isMention":false}',1785613187374);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',548,'{"_type":"chat:Message","id":"-5124234082:2808","threadId":"telegram:-5124234082","text":"Hello Peppa, I give you the inventory of fruits and vegetables that we have at home. We have 4 courgettes, 1 concombre, 1 poireau, a little celery, 2 red peppers, 8 carrots, 2 oranges, 1 aubergine, 2 citrons, 5 tomatoes Cœur de bœuf, un demi-avocat, 6 pommes de terre","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Hello Peppa, I give you the inventory of fruits and vegetables that we have at home. We have 4 courgettes, 1 concombre, 1 poireau, a little celery, 2 red peppers, 8 carrots, 2 oranges, 1 aubergine, 2 citrons, 5 tomatoes Cœur de bœuf, un demi-avocat, 6 pommes de terre","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":268,"offset":267}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":268,"offset":267}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":268,"offset":267}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-26T08:26:16.000Z","edited":false},"attachments":[],"isMention":false}',1785700063692);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',308,'{"_type":"chat:Message","id":"8641420749:816","threadId":"telegram:8641420749","text":"I didn''t run yesterday or did renfo, I needed some rest after the 4-hour night on Friday and the trip. Today I will start training again.\nDo we adapt the plan for this week then?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I didn''t run yesterday or did renfo, I needed some rest after the 4-hour night on Friday and the trip. Today I will start training again.\nDo we adapt the plan for this week then?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":41,"offset":178}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":41,"offset":178}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":41,"offset":178}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-27T10:12:47.000Z","edited":false},"attachments":[],"isMention":false}',1785751966702);
