INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',322,'{"_type":"chat:Message","id":"8641420749:548","threadId":"telegram:8641420749","text":"Salut Edmond,\nJe veux revoir ensemble le document rapport-consultant-investissement.md.\nQuelques points : \n• 1. profil famille : rajoute notre age, c''est important pour prendre en compte l''IRS Jovem, des eventuelles aides pour emprunt aux jeunes, taxes etc...\n• 1. Logement actuel : ajouter une note sur le fait que c''est certainement la moitié de la valeur du marché donc un atout a utiliser pour la strategie d''investissement. Peut etre une condition a securiser aupres de la proprietaire avant de faire un montage qui se repose trop dessus (par exemple negocier un contrat de 5 ans durant lequel le loyer ne change pas)\n• 2. \"salaire net Clément\" d''ou vient ce chiffre ? tu peux double checker si c''est correct ?\n• 2. Il manque Bonus Clément pour 2026, tu en connais la valeur ?\n• 3.1 \"vacances hors annees avec road trips exceptionnels\" je ne comprends pas ce point ? toutes les depenses de vacances devraient etre incluses.\n• 4. pour toutes les sections apres 4, j''ai modifié quelques valeurs a la main, verifie les valeurs, actifs, totaux, patrimoine net et dispo, exclus. Verifie aussi l''annexa A\n• 7. je m''interesse aussi a un autre investissement complementaire : investir dans une ou deux places de parking souterrain privees, dans le centre de lisbonne ou je pourrais installer une bonne de recharge de vehicule electrique et louer a un particulier qui a une voiture electrique. C''est un investissement que je pense rentable sur 5 ans (assumption) et surtout Lola a une reduction de 80% sur l''electricite en tant qu''employé chez EDP. A verifier : quel est le modele pour faire payer l''electricite au locataire (forfait mensuel? en fonction de la conso?...). Lola peut-elle beneficier de ces 80% si c''est pour un bien en location ? d''autres questions existent certainement...\n•","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Salut Edmond,\nJe veux revoir ensemble le document rapport-consultant-investissement.md.\nQuelques points :\n• 1. profil famille : rajoute notre age, c''est important pour prendre en compte l''IRS Jovem, des eventuelles aides pour emprunt aux jeunes, taxes etc...\n• 1. Logement actuel : ajouter une note sur le fait que c''est certainement la moitié de la valeur du marché donc un atout a utiliser pour la strategie d''investissement. Peut etre une condition a securiser aupres de la proprietaire avant de faire un montage qui se repose trop dessus (par exemple negocier un contrat de 5 ans durant lequel le loyer ne change pas)\n• 2. \"salaire net Clément\" d''ou vient ce chiffre ? tu peux double checker si c''est correct ?\n• 2. Il manque Bonus Clément pour 2026, tu en connais la valeur ?\n• 3.1 \"vacances hors annees avec road trips exceptionnels\" je ne comprends pas ce point ? toutes les depenses de vacances devraient etre incluses.\n• 4. pour toutes les sections apres 4, j''ai modifié quelques valeurs a la main, verifie les valeurs, actifs, totaux, patrimoine net et dispo, exclus. Verifie aussi l''annexa A\n• 7. je m''interesse aussi a un autre investissement complementaire : investir dans une ou deux places de parking souterrain privees, dans le centre de lisbonne ou je pourrais installer une bonne de recharge de vehicule electrique et louer a un particulier qui a une voiture electrique. C''est un investissement que je pense rentable sur 5 ans (assumption) et surtout Lola a une reduction de 80% sur l''electricite en tant qu''employé chez EDP. A verifier : quel est le modele pour faire payer l''electricite au locataire (forfait mensuel? en fonction de la conso?...). Lola peut-elle beneficier de ces 80% si c''est pour un bien en location ? d''autres questions existent certainement...\n•","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":11,"column":2,"offset":1787}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":11,"column":2,"offset":1787}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":11,"column":2,"offset":1787}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T06:37:29.000Z","edited":false},"attachments":[],"isMention":false}',1785911847137);
