INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',340,'{"_type":"chat:Message","id":"8641420749:599","threadId":"telegram:8641420749","text":"• c''est quoi la taxa de esforco ?\n• c''est quoi la carte d''approbation ? et le nom en portugais ?\n• oui le tarif reduit est \"colaborador\" pour Lola. Je peux toujours l''acheter et dire que c''est pour moi puis la louer au black (beaucoup de gens font ca ici). Ou alors faire dans les regles et ne pas beneficier des 80% de reduc, c''est toujours un investissement potentiellement interessant, a evaluer.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"• c''est quoi la taxa de esforco ?\n• c''est quoi la carte d''approbation ? et le nom en portugais ?\n• oui le tarif reduit est \"colaborador\" pour Lola. Je peux toujours l''acheter et dire que c''est pour moi puis la louer au black (beaucoup de gens font ca ici). Ou alors faire dans les regles et ne pas beneficier des 80% de reduc, c''est toujours un investissement potentiellement interessant, a evaluer.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":303,"offset":399}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":303,"offset":399}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":303,"offset":399}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T13:21:33.000Z","edited":false},"attachments":[],"isMention":false}',1785936092880);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',341,'{"_type":"chat:Message","id":"8641420749:601","threadId":"telegram:8641420749","text":"Oui chiffrons le scenario parking dans les regles.\nEn tout cas l''investissement T1 a l''air fiscalement interessant. La question demeure de savoir si on aurait les moyens d''en acheter 2 aujourd''hui puis les revendre dans 3-5 ans a la fin du regime valable jusqu''en 2029 ou au bout de 5 ans quand on veut acheter notre RP. Si pas les moyens d''en acheter 2, peut etre un T1 + quelques places de parkings + des ETFs par exemple. Mais peut etre que je vais trop vite dans les solutions, et qu''on est encore dans la face de diagnostic et d''analyse.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Oui chiffrons le scenario parking dans les regles.\nEn tout cas l''investissement T1 a l''air fiscalement interessant. La question demeure de savoir si on aurait les moyens d''en acheter 2 aujourd''hui puis les revendre dans 3-5 ans a la fin du regime valable jusqu''en 2029 ou au bout de 5 ans quand on veut acheter notre RP. Si pas les moyens d''en acheter 2, peut etre un T1 + quelques places de parkings + des ETFs par exemple. Mais peut etre que je vais trop vite dans les solutions, et qu''on est encore dans la face de diagnostic et d''analyse.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":492,"offset":542}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":492,"offset":542}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":492,"offset":542}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T13:26:31.000Z","edited":false},"attachments":[],"isMention":false}',1785936390029);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',342,'{"_type":"chat:Message","id":"8641420749:605","threadId":"telegram:8641420749","text":"Une clarification : la strategie a monter maintenant sert l''achat de la RP dans 5 ans, donc par exemple l''achat de T1 c''est dans l''idee de revendre dans 5 avant l''achat de la RP pour ainsi avoir un plus grand apport pour un pret pour la RP. Challenge that","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Une clarification : la strategie a monter maintenant sert l''achat de la RP dans 5 ans, donc par exemple l''achat de T1 c''est dans l''idee de revendre dans 5 avant l''achat de la RP pour ainsi avoir un plus grand apport pour un pret pour la RP. Challenge that","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":256,"offset":255}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":256,"offset":255}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":256,"offset":255}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T13:36:47.000Z","edited":false},"attachments":[],"isMention":false}',1785937005008);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',343,'{"_type":"chat:Message","id":"8641420749:608","threadId":"telegram:8641420749","text":"Oui c''est clair.\nQuelques commentaires du coup : \n1. l''objectif principal aujourd''hui c''est d''acheter notre RP avec l''heritage de Lola et ce qu''on peut apporter en plus, mais le constat que l''on fait est que ca ne serait pas suffisant pour la RP de nos reves au centre de Lisbonne par exemple. Donc l''idee etait de penser : on est ok de rester dans notre appart'' actuel encore quelques annees (max 5 ans) et en plus il a un loyer super interessant et en pendant ce temps \"How might we\" increase notre apport pour dans 5 ans.\n2. l''objectif retraite est donc secondaire mais a ne pas negliger.\n3. evaluons donc aussi l''impact du T1 sur la taxa de esforco dans 5 ans\nQue dis-tu de tout ca ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Oui c''est clair.\nQuelques commentaires du coup :","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":32,"offset":48}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":33,"offset":49}}},{"type":"list","ordered":true,"start":1,"spread":false,"children":[{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"l''objectif principal aujourd''hui c''est d''acheter notre RP avec l''heritage de Lola et ce qu''on peut apporter en plus, mais le constat que l''on fait est que ca ne serait pas suffisant pour la RP de nos reves au centre de Lisbonne par exemple. Donc l''idee etait de penser : on est ok de rester dans notre appart'' actuel encore quelques annees (max 5 ans) et en plus il a un loyer super interessant et en pendant ce temps \"How might we\" increase notre apport pour dans 5 ans.","position":{"start":{"line":3,"column":4,"offset":53},"end":{"line":3,"column":475,"offset":524}}}],"position":{"start":{"line":3,"column":4,"offset":53},"end":{"line":3,"column":475,"offset":524}}}],"position":{"start":{"line":3,"column":1,"offset":50},"end":{"line":3,"column":475,"offset":524}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"l''objectif retraite est donc secondaire mais a ne pas negliger.","position":{"start":{"line":4,"column":4,"offset":528},"end":{"line":4,"column":67,"offset":591}}}],"position":{"start":{"line":4,"column":4,"offset":528},"end":{"line":4,"column":67,"offset":591}}}],"position":{"start":{"line":4,"column":1,"offset":525},"end":{"line":4,"column":67,"offset":591}}},{"type":"listItem","spread":false,"checked":null,"children":[{"type":"paragraph","children":[{"type":"text","value":"evaluons donc aussi l''impact du T1 sur la taxa de esforco dans 5 ans\nQue dis-tu de tout ca ?","position":{"start":{"line":5,"column":4,"offset":595},"end":{"line":6,"column":24,"offset":687}}}],"position":{"start":{"line":5,"column":4,"offset":595},"end":{"line":6,"column":24,"offset":687}}}],"position":{"start":{"line":5,"column":1,"offset":592},"end":{"line":6,"column":24,"offset":687}}}],"position":{"start":{"line":3,"column":1,"offset":50},"end":{"line":6,"column":24,"offset":687}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":6,"column":24,"offset":687}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T14:13:46.000Z","edited":false},"attachments":[],"isMention":false}',1785939224758);
