INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',352,'{"_type":"chat:Message","id":"8641420749:865","threadId":"telegram:8641420749","text":"Finalement on voyage vendredi. Donc demain j’ai full dispo. Vendredi voyage, pas dispo, samedi et dimanche dispo a nouveau. \nComment on adapte ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Finalement on voyage vendredi. Donc demain j’ai full dispo. Vendredi voyage, pas dispo, samedi et dimanche dispo a nouveau.\nComment on adapte ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":20,"offset":144}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":20,"offset":144}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":20,"offset":144}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-29T18:54:06.000Z","edited":false},"attachments":[],"isMention":false}',1785956042861);
