INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',566,'{"_type":"chat:Message","id":"-5124234082:2859","threadId":"telegram:-5124234082","text":"Pas de panier cette semaine, on part demain. Maximiser finir aujourd’hui ce qui ne se garde pas, donc ne pas utiliser ce qui est au congel. Et donne moi une recette d’un wrap que Maola va aimer pour son pique nique aujourd’hui","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pas de panier cette semaine, on part demain. Maximiser finir aujourd’hui ce qui ne se garde pas, donc ne pas utiliser ce qui est au congel. Et donne moi une recette d’un wrap que Maola va aimer pour son pique nique aujourd’hui","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":227,"offset":226}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":227,"offset":226}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":227,"offset":226}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T07:05:54.000Z","edited":false},"attachments":[],"isMention":false}',1785999954423);
