INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',368,'{"_type":"chat:Message","id":"8641420749:894","threadId":"telegram:8641420749","text":"/done I felt good today, so on the Z2 phase I tried to be as close as possible to 128, the top of my zone 2, without passing it. So I think the average is 123 or 124 on that Z2 phase.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"/done I felt good today, so on the Z2 phase I tried to be as close as possible to 128, the top of my zone 2, without passing it. So I think the average is 123 or 124 on that Z2 phase.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":184,"offset":183}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":184,"offset":183}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":184,"offset":183}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T11:44:15.000Z","edited":false},"attachments":[],"isMention":false}',1786016654421);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',576,'{"_type":"chat:Message","id":"-5124234082:2885","threadId":"telegram:-5124234082","text":"Je veux que Branca fasse de la soupe ajd pour qu’on l’emmene en Espagne demain. Si elle l’a fait aujourd’hui, que je la garde au frigo ce soir, sac isotherme demain toute la journée puis congelateur en fin de journee, pas de probleme ?\nDonne moi une bonne recette qui plaira aux enfants avec des legumes que je peux acheter cet aprem","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je veux que Branca fasse de la soupe ajd pour qu’on l’emmene en Espagne demain. Si elle l’a fait aujourd’hui, que je la garde au frigo ce soir, sac isotherme demain toute la journée puis congelateur en fin de journee, pas de probleme ?\nDonne moi une bonne recette qui plaira aux enfants avec des legumes que je peux acheter cet aprem","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":98,"offset":333}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":98,"offset":333}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":2,"column":98,"offset":333}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-07-30T11:53:06.000Z","edited":false},"attachments":[],"isMention":false}',1786017184892);
